nextflow_process {

    name "Test Process SOMALIER_RELATE"
    script "../main.nf"
    process "SOMALIER_RELATE"

    tag "modules"
    tag "modules_nfcore"
    tag "somalier"
    tag "somalier/relate"

    test("[ delete_me, [] ], []") {

        when {
            process {
                """
                input[0] = [
                    [ id:'cohort', single_end:false ], // meta map
                    [
                     file(params.modules_testdata_base_path + 'delete_me/somalier/normal.somalier', checkIfExists: true),
                     file(params.modules_testdata_base_path + 'delete_me/somalier/tumour.somalier', checkIfExists: true)
                    ],
                    []
                ]
                input[1] = []
                input[2] = [ [:], [] ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("[ delete_me, [] ], [], sites") {

        when {
            process {
                """
                input[0] = [
                    [ id:'cohort', single_end:false ], // meta map
                    [
                     file(params.modules_testdata_base_path + 'delete_me/somalier/normal.somalier', checkIfExists: true),
                     file(params.modules_testdata_base_path + 'delete_me/somalier/tumour.somalier', checkIfExists: true)
                    ],
                    []
                ]
                input[1] = []
                input[2] = [
                    [ id:'hg38' ],
                    file(params.modules_testdata_base_path + 'delete_me/somalier/sites_chr21.hg38.vcf.gz', checkIfExists: true)
                ]
                """
            }
        }

        then {
            def samples = path(process.out.samples_tsv[0][1]).readLines()
            def charr = (samples[0].split('\t') as List).indexOf('contamination_charr')
            assertAll(
                { assert process.success },
                // with --sites, contamination_charr is estimated instead of NaN
                { assert charr >= 0 },
                { assert !samples[1].split('\t')[charr].equalsIgnoreCase('nan') },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("[ delete_me, ped ], groups") {

        when {
            process {
                """
                input[0] = [
                    [ id:'cohort', single_end:false ], // meta map
                    [
                     file(params.modules_testdata_base_path + 'delete_me/somalier/normal.somalier', checkIfExists: true),
                     file(params.modules_testdata_base_path + 'delete_me/somalier/tumour.somalier', checkIfExists: true)
                    ],
                    file(params.modules_testdata_base_path + 'delete_me/somalier/family.ped', checkIfExists: true)
                ]
                input[1] = file(params.modules_testdata_base_path + 'delete_me/somalier/groups.txt', checkIfExists: true)
                input[2] = [ [:], [] ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("[ delete_me, [] ], [] -stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'cohort', single_end:false ], // meta map
                    [
                     file(params.modules_testdata_base_path + 'delete_me/somalier/normal.somalier', checkIfExists: true),
                     file(params.modules_testdata_base_path + 'delete_me/somalier/tumour.somalier', checkIfExists: true)
                    ],
                    []
                ]
                input[1] = []
                input[2] = [ [:], [] ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("[ delete_me, ped ], groups -stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'cohort', single_end:false ], // meta map
                    [
                     file(params.modules_testdata_base_path + 'delete_me/somalier/normal.somalier', checkIfExists: true),
                     file(params.modules_testdata_base_path + 'delete_me/somalier/tumour.somalier', checkIfExists: true)
                    ],
                    file(params.modules_testdata_base_path + 'delete_me/somalier/family.ped', checkIfExists: true)
                ]
                input[1] = file(params.modules_testdata_base_path + 'delete_me/somalier/groups.txt', checkIfExists: true)
                input[2] = [ [:], [] ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

}

